 .binary-rain{position:fixed;inset:0;width:100vw;height:100vh;z-index:50;background:var(--void)}.access-overlay{position:fixed;inset:0;z-index:51;display:grid;place-content:center;text-align:center;color:var(--green);font-size:clamp(28px,6vw,72px);font-weight:bold;letter-spacing:.12em;text-shadow:0 0 18px var(--green);background:#03080555}.access-overlay span{display:block;font-size:11px;letter-spacing:.18em;color:var(--mint);margin-top:16px}.challenge-card{width:min(620px,90vw);border:1px solid var(--green);background:#07150cf7;padding:32px;box-shadow:0 0 40px #00ff6630}.challenge-kicker{color:var(--muted);font-size:11px;letter-spacing:.15em}.challenge-card h1{font-size:clamp(22px,5vw,36px);color:var(--green);margin:14px 0}.challenge-card h1 span{display:block;color:var(--mint);font-size:.45em;letter-spacing:.16em}.challenge-card p{color:#b4d9ba;font-size:13px}.cipher-bars{display:grid;gap:18px;margin:28px 0}.cipher-row{display:grid;grid-template-columns:78px 1fr;align-items:center;gap:12px;font-size:11px}.cipher-track{height:18px;position:relative;border:1px solid var(--line);background:#020703;cursor:pointer}.cipher-track:after{content:"";position:absolute;left:25%;width:37%;top:0;bottom:0;background:#00ff662d;border-left:1px solid var(--green);border-right:1px solid var(--green)}.cipher-track i{position:absolute;z-index:1;left:0;top:2px;width:12%;height:12px;background:var(--mint);box-shadow:0 0 8px var(--green);transition:left .08s linear}.cipher-track.locked i{background:var(--green)}.challenge-meta{display:flex;justify-content:space-between;color:var(--green);font-size:12px}.bypass-button{float:right;border:0;background:transparent;color:var(--muted);font-size:11px;margin-top:18px}.bypass-button:hover{color:var(--green)}
 .desktop-widgets{position:absolute;right:24px;top:150px;width:225px;display:grid;gap:12px;z-index:1}.telemetry-widget,.notes-widget{border:1px solid var(--line);background:#07150ce8;padding:13px;box-shadow:0 0 20px #0008}.telemetry-widget h3,.notes-widget h3{color:var(--green);font-size:11px;letter-spacing:.1em;margin:0 0 12px}.telemetry-line{display:flex;justify-content:space-between;font-size:11px;margin:8px 0}.telemetry-line b{color:var(--green)}.telemetry-line .stable{color:#a7ffb8}.telemetry-bar{height:7px;background:#020703;border:1px solid var(--line)}.telemetry-bar i{display:block;width:15%;height:100%;background:var(--green);transition:width .35s cubic-bezier(.22,1,.36,1)}.notes-widget label{display:block;font-size:11px;margin:9px 0}.notes-widget input[type=checkbox]{accent-color:var(--green)}#note-form{display:flex;margin-top:12px}#note-input{width:100%;min-width:0;background:#020703;border:1px solid var(--line);color:var(--mint);padding:5px;font-size:10px}#note-form button{border:1px solid var(--green);background:#102c18;color:var(--green);width:28px}.notes-widget ul{padding-left:15px;margin:7px 0 0;color:var(--muted);font-size:10px}
 @media(max-width:700px){.desktop-icons{grid-template-columns:repeat(4,70px);gap:15px 12px;padding:20px 12px}.status-bar{padding:0 10px}.status-readout{gap:8px}.github-link{display:none}.toast{min-width:0;width:calc(100vw - 30px)}#toast-stack{right:15px}.taskbar{height:42px}}
 @media(max-width:900px){.desktop-widgets{position:relative;right:auto;top:auto;width:min(460px,calc(100vw - 24px));margin:6px 12px 70px;grid-template-columns:repeat(2,1fr)}}
 @media(max-width:560px){.desktop-widgets{grid-template-columns:1fr}}
